import { validateAccessibleCorpus } from '../bank';
import { ACCESSIBLE_CATEGORY_TITLES } from '../categoryNames';
import { LEGACY_EASY_TARGETS } from '../targets';
import type { AccessibleCategory, AccessibleQuestion } from '../types';

const ASSIGNED_BATCHES = new Set([
  '05-art-architecture',
  '12-mythology-religion-philosophy',
]);

const assignedTargets = LEGACY_EASY_TARGETS.filter(({ batchId }) =>
  ASSIGNED_BATCHES.has(batchId));

const titleById = new Map(
  ACCESSIBLE_CATEGORY_TITLES
    .filter(({ batchId }) => ASSIGNED_BATCHES.has(batchId))
    .map((title) => [title.categorySetId, title] as const),
);

type Bilingual = readonly [en: string, et: string];
type Variants = readonly [en: readonly string[], et: readonly string[]];
type Tier = 1 | 2 | 3 | 4 | 5;

type QuestionSeed = readonly [
  tier: Tier,
  key: string,
  subjectKey: string,
  clue: Bilingual,
  response: Bilingual,
  variants: Variants,
  explanation: Bilingual,
  sourceTitle: string,
  sourcePath: string,
];

function question(seed: QuestionSeed): AccessibleQuestion {
  const [
    tier,
    key,
    subjectKey,
    clue,
    response,
    variants,
    explanation,
    sourceTitle,
    sourcePath,
  ] = seed;
  return {
    tier,
    key,
    subjectKey,
    clue: { en: clue[0], et: clue[1] },
    response: { en: response[0], et: response[1] },
    acceptedVariants: { en: variants[0], et: variants[1] },
    explanation: { en: explanation[0], et: explanation[1] },
    source: {
      sourceId: `wikipedia:${key}`,
      title: `${sourceTitle} — Wikipedia`,
      url: `https://en.wikipedia.org/wiki/${sourcePath}`,
      license: 'CC-BY-SA-4.0',
      retrievedAt: '2026-08-28',
    },
  };
}

