const rawCategories: readonly AccessibleCategory[] = assignedTargets.map((target) => {
  const title = titleById.get(target.categorySetId);
  if (title === undefined) {
    throw new Error(`Missing approved category title: ${target.categorySetId}`);
  }
  const seeds = QUESTION_SEEDS[target.categorySetId];
  if (seeds === undefined) {
    throw new Error(`Missing authored category: ${target.categorySetId}`);
  }
  return {
    categorySetId: target.categorySetId,
    batchId: target.batchId,
    name: title.name,
    questions: seeds.map(question),
  };
});

export const ART_MYTHOLOGY_CATEGORIES = validateAccessibleCorpus(
  rawCategories,
  assignedTargets,
);
